local api = { }
local function connect ( signal , callback )
table . insert ( connections , signal : Connect ( callback ) )
end
local function stop_flight ( )
local was_flying = flight_velocity ~= nil
if flight_velocity then
flight_velocity : Destroy ( )
flight_velocity = nil
end
if flight_attachment then
flight_attachment : Destroy ( )
flight_attachment = nil
end
if humanoid and originals then
humanoid . PlatformStand = originals . PlatformStand
humanoid . AutoRotate = originals . AutoRotate
end
if was_flying and root and root . Parent then
root . AssemblyLinearVelocity = Vector3 . zero
end
end
local function apply ( )
if not humanoid then
return
end
humanoid . WalkSpeed = speed_override or originals . WalkSpeed
if jump_override then
humanoid . UseJumpPower = false
humanoid . JumpHeight = jump_override
else
humanoid . JumpHeight = originals . JumpHeight
humanoid . UseJumpPower = originals . UseJumpPower
end
end
local function restore ( )
stop_flight ( )
if humanoid and humanoid . Parent and originals then
humanoid . WalkSpeed = originals . WalkSpeed
humanoid . JumpHeight = originals . JumpHeight
humanoid . UseJumpPower = originals . UseJumpPower
end
end
local function attach ( model )
restore ( )
character , humanoid , root , originals = model , nil , nil , nil
end
local function resolve_character ( )
if not character or not character . Parent then
return
end
if not humanoid then
humanoid = character : FindFirstChildOfClass ( "\072\117\109\097\110\111\105\100" )
root = character : FindFirstChild ( "\072\117\109\097\110\111\105\100\082\111\111\116\080\097\114\116" )
if humanoid and root then
originals = {
WalkSpeed = humanoid . WalkSpeed ,
JumpHeight = humanoid . JumpHeight ,
UseJumpPower = humanoid . UseJumpPower ,
PlatformStand = humanoid . PlatformStand ,
AutoRotate = humanoid . AutoRotate ,
}
apply ( )
else
humanoid = nil
end
end
end
local function clear_visual ( target )
local visual = visuals [ target ]
if visual then
visual . box : Destroy ( )
visual . label : Destroy ( )
visuals [ target ] = nil
end
end
local function clear_esp ( )
for target in visuals do
clear_visual ( target )
end
end
local function update_esp ( )
if not esp or not root then
clear_esp ( )
return
end
local keep = { }
local count = 0
for _ , target in players : GetPlayers ( ) do
local model = target . Character
local target_root = model and model : FindFirstChild ( "\072\117\109\097\110\111\105\100\082\111\111\116\080\097\114\116" )
local target_humanoid = model and model : FindFirstChildOfClass ( "\072\117\109\097\110\111\105\100" )
local same_team = player . Team ~= nil and target . Team == player . Team
if
target ~= player
and target_root
and target_humanoid
and target_humanoid . Health > 0
and not ( options . Team and same_team )
then
local distance = ( target_root . Position - root . Position ) . Magnitude
if distance <= config . esp_distance and count < config . esp_limit then
count += 1
keep [ target ] = true
local visual = visuals [ target ]
if visual and visual . model ~= model then
clear_visual ( target )
visual = nil
end
if not visual then
local box = create ( "\083\101\108\101\099\116\105\111\110\066\111\120" )
box . Name = "\075\111\100\101\120\069\115\112\066\111\120"
box . Adornee = model
box . LineThickness = 0.03
box . SurfaceTransparency = 1
box . Parent = services . Owner
local billboard = create ( "\066\105\108\108\098\111\097\114\100\071\117\105" )
billboard . Name = "\075\111\100\101\120\069\115\112\076\097\098\101\108"
billboard . Adornee = target_root
billboard . AlwaysOnTop = true
billboard . Size = UDim2 . fromOffset ( 200 , 48 )
billboard . StudsOffset = Vector3 . new ( 0 , 4 , 0 )
billboard . Parent = services . Owner
local label = create ( "\084\101\120\116\076\097\098\101\108" )
label . Size = UDim2 . fromScale ( 1 , 1 )
label . BackgroundTransparency = 1
label . Font = Enum . Font . BuilderSansBold
label . TextSize = 14
label . TextStrokeTransparency = 0.5
label . Parent = billboard
visual = { box = box , label = billboard , text = label , model = model }
visuals [ target ] = visual
end
visual . box . Visible = options . Boxes
visual . box . Color3 = esp_colour
visual . label . Enabled = options . Names or options . Distance
visual . text . TextColor3 = esp_colour
visual . text . Text = ( options . Names and target . DisplayName or "" )
.. ( options . Distance and string . format ( "\032\032\037\100\109" , distance ) or "" )
end
end
end
for target in visuals do
if not keep [ target ] then
clear_visual ( target )
end
end
end
function api . SetSpeed ( value )
speed_override = value
apply ( )
end
function api . SetJump ( value )
jump_override = value
apply ( )
end
function api . ResetSpeed ( )
speed_override = nil
apply ( )
return originals and originals . WalkSpeed or 16
end
function api . ResetJump ( )
jump_override = nil
apply ( )
return originals and originals . JumpHeight or 7.2
end
function api . SetFly ( value )
fly = value
if not value then
stop_flight ( )
end
end
function api . SetInfiniteJump ( value )
inf_jump = value
end
function api . SetEsp ( value )
esp = value
if not value then
clear_esp ( )
end
end
function api . SetEspOption ( name , value )
options [ name ] = value
end
function api . SetEspColour ( value )
esp_colour = value
end
function api . Defaults ( )
return originals and originals . WalkSpeed or 16 , originals and originals . JumpHeight or 7.2
end
connect ( player . CharacterAdded , attach )
connect ( input . JumpRequest , function ( )
if inf_jump and humanoid and humanoid . Health > 0 and not input : GetFocusedTextBox ( ) then
humanoid : ChangeState ( Enum . HumanoidStateType . Jumping )
end
end )
connect ( run . RenderStepped , function ( dt )
if not alive then
return
end
resolve_character ( )
