flight_attachment . Name = "\075\111\100\101\120\070\108\105\103\104\116\065\116\116\097\099\104\109\101\110\116"
flight_attachment . Parent = root
flight_velocity = create ( "\076\105\110\101\097\114\086\101\108\111\099\105\116\121" )
flight_velocity . Name = "\075\111\100\101\120\070\108\105\103\104\116\086\101\108\111\099\105\116\121"
flight_velocity . Attachment0 = flight_attachment
flight_velocity . RelativeTo = Enum . ActuatorRelativeTo . World
flight_velocity . ForceLimitsEnabled = false
flight_velocity . Parent = root
end
humanoid . PlatformStand = true
humanoid . AutoRotate = false
local direction = Vector3 . zero
local camera = world . CurrentCamera
if camera and not input : GetFocusedTextBox ( ) then
if input : IsKeyDown ( Enum . KeyCode . W ) then
direction += camera . CFrame . LookVector
end
if input : IsKeyDown ( Enum . KeyCode . S ) then
direction -= camera . CFrame . LookVector
end
if input : IsKeyDown ( Enum . KeyCode . D ) then
direction += camera . CFrame . RightVector
end
if input : IsKeyDown ( Enum . KeyCode . A ) then
direction -= camera . CFrame . RightVector
end
if input : IsKeyDown ( Enum . KeyCode . Space ) then
direction += Vector3 . yAxis
end
if input : IsKeyDown ( Enum . KeyCode . LeftControl ) then
direction -= Vector3 . yAxis
end
end
flight_velocity . VectorVelocity = direction . Magnitude > 0 and direction . Unit * config . fly_speed
or Vector3 . zero
elseif flight_velocity then
stop_flight ( )
end
elapsed += dt or 0
if elapsed >= config . esp_update_seconds then
elapsed = 0
update_esp ( )
end
end )
if player . Character then
attach ( player . Character )
resolve_character ( )
end
function api . Destroy ( )
alive = false
restore ( )
clear_esp ( )
for _ , connection in connections do
connection : Disconnect ( )
end
end
return api
end
return LocalGameplay
