local TextService = game : GetService ( "\084\101\120\116\083\101\114\118\105\099\101" )
local display_epoch = 0
local function measure_text ( contents , font_size , available_width )
local ok , dimensions = pcall ( function ( )
return TextService : GetTextSize (
contents ,
font_size ,
Enum . Font . BuilderSans ,
Vector2 . new ( available_width , 2000 )
)
end )
if ok and dimensions then
return math . max ( font_size + 4 , math . ceil ( dimensions . Y ) + 5 )
end
local approximate_lines =
math . max ( 1 , math . ceil ( # contents / math . max ( 1 , math . floor ( available_width / ( font_size * 0.53 ) ) ) ) )
return approximate_lines * ( font_size + 6 ) + 6
end
local function remove_old_cards ( )
for _ , child in scroll : GetChildren ( ) do
